vec2 rs, rs0, uv2, uv3,uv4,uv6, uv8;
vec3 noise, ret1, ret2, ret3;

void main() {
  vec3 ret = vec3(0.0);
  vec2 uv = vUv;
  vec2 uv_orig = vUvOriginal;
  float rad = vRadius;
  float ang = vAngle;
  uv8 = uv_orig;
uv.y = uv.y-.1;
vec2 uv1 = (uv-.5 )*uAspect.xy;
float z = .1/uv1.y/uv1.x;
z = .3/uv1.y;
rs0.x = uv1.x*z;
rs0.y = z;
rs.x = rs0.x + uTime / 2.0;
rs.y = rs0.y + uTime;
noise = lum(texture(sampler_noise_hq,rs / 2.0));
noise = noise-.55;
float mask = clamp01(12.0 * (uv1.y));
uv2 = uv1+.5;
//uv2 *= uAspect.yx;
uv3 =fract(uv2-noise*.1*mask );
vec2 hor = vec2 ((1.0/uTexSize.x), 0.0 );
vec2 ver = vec2 ( 0.0 , (1.0/uTexSize.y));
float dx = lum(GetPixel(uv3+hor) - GetPixel(uv3-hor).xy);
float dy = lum(GetPixel(uv3+ver) - GetPixel(uv3-ver).xy);
vec2 dz = vec2 (dx,dy);
//dz *= (length(dz) >= .01);
uv3 += dz * (1.0 - mask);
//Strahl
uv4 = vec2(.5,uv1.x/uv1.y);
uv4 = fract(.06*audioLowSmooth*uv4);
vec3 col = 1;
vec3 ret3 = GetPixel(uv4 * 14.0);
ret3 += (.008/(length(uv1)))*col;
//ret2 *= q10;
vec3 mus = .02 / (length(uv1+.45+dz * 16.0));
float mus2 = clamp01(.01*abs(uv3.x-.5)/abs(uv3.y-.55)-dz * 4.0);
float stars = clamp01(1.0 / ((uv.x * 3234224.0*uv.y)%22345));
ret1 = GetPixel(fract(uv3));
ret1 *= 1.0 - mask / 2.0;;
float fmask = clamp01(1.0 - lum(ret1 * 4.0));
ret2 = ret1  + mus * (1.0 - mask) * 2.0  ;
ret = max(ret2, stars*(1.0 - mask)*fmask) ;
ret += clamp01(q22*mus2*fmask);
  fragColor = vec4(ret, 1.0);
}

